using System.Text.RegularExpressions; using InovaGed.Environment.Doctor.Quality;
namespace InovaGed.Environment.Doctor.Checks;
public sealed class DependencyInjectionQualityCheck:IQualityCheck { public string Name=>"DI"; private static readonly string[] Essential=["IPcdVersionResolver","IRetentionDestinationRepository","IRetentionAuditWriter","ILabelTemplateCatalogService","ILabelPrintJobService","ILabelPdfRenderService","ILabelPrintRegistrar","ILabelPayloadBuilder","ILabelQrCodeService","InstrumentVersionRepository"];
 public Task<IReadOnlyList<QualityFinding>> RunAsync(QualityContext c,CancellationToken ct){var program=ReadComposition(c.Root); var all=string.Join('\n',Directory.EnumerateFiles(Path.Combine(c.Root,"InovaGed.Web"),"*.cs",SearchOption.AllDirectories).Select(File.ReadAllText));var r=Essential.Select(x=>program.Contains(x,StringComparison.Ordinal)?new QualityFinding(Name,QualityStatus.Pass,$"Serviço registrado: {x}",Resource:"InovaGed.Web/Program.cs"):new QualityFinding(Name,QualityStatus.Fail,$"Serviço DI essencial ausente: {x}","Controllers podem falhar ao ativar.",$"Registrar services.AddScoped<{x}, implementação>();",Resource:"InovaGed.Web/Program.cs")).ToList(); var controllers=Regex.Matches(all,@"public\s+(\w+Controller)\s*\(([^)]*)\)").Cast<Match>().ToArray(); r.Add(new(Name,controllers.Length>0?QualityStatus.Pass:QualityStatus.Fail,$"{controllers.Length} construtores de controllers mapeados por análise estática.","Ações de negócio não foram executadas.","Execute com a aplicação configurada para validação dinâmica."));return Task.FromResult<IReadOnlyList<QualityFinding>>(r);}
 private static string ReadComposition(string root){var files=new List<string>{Path.Combine(root,"InovaGed.Web/Program.cs"),Path.Combine(root,"InovaGed.Infrastructure/DependencyInjection.cs")};if(Directory.Exists(root))files.AddRange(Directory.EnumerateFiles(root,"*DependencyInjection.cs",SearchOption.AllDirectories).Where(path=>!path.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}",StringComparison.OrdinalIgnoreCase)&&!path.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}",StringComparison.OrdinalIgnoreCase)));return string.Join('\n',files.Distinct(StringComparer.OrdinalIgnoreCase).Where(File.Exists).Select(File.ReadAllText));}
}
